import sys

def find_permutations(k, a):
    n = 1 << k
    used = [False] * n
    p = [-1] * n
    q = [-1] * n

    def backtrack(i):
        if i == n:
            return True
        for x in range(n):
            if not used[x]:
                y = x ^ a[i]
                if 0 <= y < n and not used[y]:
                    used[x] = used[y] = True
                    p[i] = x
                    q[i] = y
                    if backtrack(i + 1):
                        return True
                    used[x] = used[y] = False
        return False

    if backtrack(0):
        return "Shi\n" + " ".join(map(str, p)) + "\n" + " ".join(map(str, q))
    else:
        return "Fou"

input = sys.stdin.read().split()
k = int(input[0])
a = list(map(int, input[1:]))
print(find_permutations(k, a))
